// The template model entry for a model id, or nullptr for any other model.
inline const UnitTemplateModel *find_unit_template_model(const char *id) {
	if (!id) return nullptr;
	const UnitTemplateModel *t = unit_template_models();
	for (int i = 0; i < UNIT_TEMPLATE_MODEL_COUNT; ++i)
		if (std::strcmp(t[i].id, id) == 0) return &t[i];
	return nullptr;
}

static_assert(CIV_UNIT_TEMPLATE_COUNT == 457, "rerun tools/extract_0ad_assets.py --templates");

